# AUTO-GENERATED by QuroHarness | source: QuroHarness | date: 2026-10-25
<#
.SYNOPSIS
  QuroERP Harness 문서 구조를 검사한다. 오류가 있으면 exit 1.
.DESCRIPTION
  - 필수 파일·폴더
  - AGENTS.md 150줄 이내
  - docs/ 아래 모든 MD가 docs/INDEX.md에 등록되어 있는지
  - MD 안의 상대 경로 링크가 실제 파일을 가리키는지
  - .claude/skills 가 .agents/skills 와 같은지
  - harness/tasks/*.json 필수 필드
#>
param([string]$Root = (Split-Path -Parent $PSScriptRoot))

$ErrorActionPreference = 'Stop'
$errors = [System.Collections.Generic.List[string]]::new()
function Fail($msg) { $errors.Add($msg) }

$required = @(
  'AGENTS.md', 'CLAUDE.md', 'GEMINI.md', 'docs/INDEX.md', 'docs/glossary.md', 'docs/architecture',
  'docs/business-rules/MM', 'docs/business-rules/SD', 'docs/business-rules/FI', 'docs/business-rules/PP', 'docs/business-rules/CO',
  'docs/specifications', '.agents/skills', '.claude/skills', 'harness/tasks', 'harness/plans', 'harness/manifests',
  'scripts/generate-harness.ps1', 'scripts/validate-harness.ps1', 'src', 'tests'
)
foreach ($p in $required) { if (-not (Test-Path (Join-Path $Root $p))) { Fail "필수 경로 없음: $p" } }
foreach ($s in 'quro-api', 'quro-blazor', 'quro-dapper', 'quro-unit-test', 'quro-code-review') {
  if (-not (Test-Path (Join-Path $Root ".agents/skills/$s/SKILL.md"))) { Fail "스킬 없음: $s" }
}

$agents = Join-Path $Root 'AGENTS.md'
if (Test-Path $agents) {
  $n = (Get-Content $agents -Encoding utf8).Count
  if ($n -gt 150) { Fail "AGENTS.md가 150줄을 넘는다 ($($n)줄)" }
}

$docs = Join-Path $Root 'docs'
$index = Join-Path $docs 'INDEX.md'
if (Test-Path $index) {
  $indexText = Get-Content $index -Raw -Encoding utf8
  Get-ChildItem $docs -Recurse -Filter *.md | ForEach-Object {
    $rel = [IO.Path]::GetRelativePath($docs, $_.FullName).Replace('\', '/')
    if ($rel -eq 'INDEX.md') { return }
    if ($indexText -notmatch [regex]::Escape("($rel)")) { Fail "INDEX.md에 없음: docs/$rel" }
  }
}

Get-ChildItem $Root -Recurse -Filter *.md | Where-Object { $_.FullName -notmatch '[\\/](src|tests|\.git)[\\/]' } | ForEach-Object {
  $file = $_
  $text = Get-Content $file.FullName -Raw -Encoding utf8
  foreach ($m in [regex]::Matches($text, '\]\(([^)#:\s]+\.(md|json|ps1))(#[^)]*)?\)')) {
    $target = Join-Path $file.DirectoryName $m.Groups[1].Value
    if (-not (Test-Path $target)) { Fail "깨진 링크: $([IO.Path]::GetRelativePath($Root, $file.FullName)) → $($m.Groups[1].Value)" }
  }
}

$a = Join-Path $Root '.agents/skills'; $c = Join-Path $Root '.claude/skills'
if ((Test-Path $a) -and (Test-Path $c)) {
  $hash = { param($dir) Get-ChildItem $dir -Recurse -File | ForEach-Object {
      "$([IO.Path]::GetRelativePath($dir, $_.FullName).Replace('\','/'))=$((Get-FileHash $_.FullName).Hash)" } | Sort-Object }
  if (Compare-Object (& $hash $a) (& $hash $c)) { Fail '.claude/skills 가 .agents/skills 와 다르다. scripts/generate-harness.ps1 -Mirror 를 실행한다' }
}

# 공개 저장소 검사: 비공개 Harness 저장소의 결정·이슈 번호, 경로, 레거시 시스템 이름·취약점 언급이 없어야 한다
$private = 'ADR-\d{4}', 'ISSUE-\d{3}', '(?i)procentro', '(?i)base64', '\bmapping/', '\banalysis/', '\bdecisions/', 'harness/build_', '\bsource/'
Get-ChildItem $Root -Recurse -File -Include *.md, *.json | Where-Object { $_.FullName -notmatch '[\/](src|tests|\.git)[\/]' } | ForEach-Object {
  $text = Get-Content $_.FullName -Raw -Encoding utf8
  foreach ($p in $private) {
    if ($text -match $p) { Fail "공개 불가 내용: $([IO.Path]::GetRelativePath($Root, $_.FullName)) — '$($Matches[0])'" }
  }
}

$fields = 'id', 'title', 'module', 'layer', 'screenType', 'specs', 'rules', 'skills', 'dependsOn', 'acceptance', 'estimateHours', 'status'
$taskIds = @{}
Get-ChildItem (Join-Path $Root 'harness/tasks') -Filter *.json -ErrorAction SilentlyContinue | ForEach-Object {
  $t = Get-Content $_.FullName -Raw -Encoding utf8 | ConvertFrom-Json
  foreach ($f in $fields) { if (-not ($t.PSObject.Properties.Name -contains $f)) { Fail "$($_.Name): 필드 없음 $f" } }
  foreach ($s in $t.specs) { if (-not (Test-Path (Join-Path $Root $s))) { Fail "$($_.Name): 명세 없음 $s" } }
  $taskIds[$t.id] = $t
}
foreach ($t in $taskIds.Values) { foreach ($d in $t.dependsOn) { if (-not $taskIds.ContainsKey($d)) { Fail "$($t.id): dependsOn 대상 없음 $d" } } }

if ($errors.Count) { $errors | ForEach-Object { Write-Host "❌ $_" }; Write-Host "오류 $($errors.Count)건"; exit 1 }
Write-Host '✅ Harness 검증 통과'
